(function(){
  const isDark = () => {
    const t = document.documentElement.getAttribute('data-theme');
    if(t === 'dark') return true;
    if(t === 'light') return false;
    return window.matchMedia('(prefers-color-scheme: dark)').matches;
  };

  function css(v){ return getComputedStyle(document.documentElement).getPropertyValue(v).trim(); }

  function barChart(containerId, data, opts){
    // data: [{label, value}], opts: {color, valueFmt, suffix}
    const el = document.getElementById(containerId);
    if(!el) return;
    const W = 380, H = 190, padL = 6, padR = 6, padT = 18, padB = 26;
    const plotW = W - padL - padR, plotH = H - padT - padB;
    const n = data.length;
    const gap = 14;
    const bw = (plotW - gap*(n-1)) / n;
    const max = Math.max(...data.map(d=>d.value)) * 1.15;
    const min = Math.min(0, Math.min(...data.map(d=>d.value)));
    const scaleY = v => plotH - ( (v - min) / (max - min) ) * plotH;

    const svgNS = "http://www.w3.org/2000/svg";
    const svg = document.createElementNS(svgNS,"svg");
    svg.setAttribute("viewBox", `0 0 ${W} ${H}`);
    svg.setAttribute("style","max-width:100%;height:auto;font-family:'IBM Plex Mono',monospace;");
    svg.setAttribute("role","img");
    svg.setAttribute("aria-label", opts.aria || "");

    const g = document.createElementNS(svgNS,"g");
    g.setAttribute("transform", `translate(${padL},${padT})`);
    svg.appendChild(g);

    // baseline
    const base = document.createElementNS(svgNS,"line");
    base.setAttribute("x1",0); base.setAttribute("x2",plotW);
    base.setAttribute("y1",scaleY(0)); base.setAttribute("y2",scaleY(0));
    base.setAttribute("stroke","var(--chart-grid)"); base.setAttribute("stroke-width","1");
    g.appendChild(base);

    data.forEach((d,i)=>{
      const x = i*(bw+gap);
      const y0 = scaleY(0), y1 = scaleY(d.value);
      const top = Math.min(y0,y1), h = Math.abs(y1-y0);
      const rect = document.createElementNS(svgNS,"rect");
      rect.setAttribute("x",x); rect.setAttribute("y",top);
      rect.setAttribute("width",bw); rect.setAttribute("height",Math.max(h,2));
      rect.setAttribute("rx",3);
      rect.setAttribute("fill", d.emph ? opts.color : opts.colorMuted);
      rect.style.cursor="pointer";
      g.appendChild(rect);

      const lbl = document.createElementNS(svgNS,"text");
      lbl.setAttribute("x", x+bw/2); lbl.setAttribute("y", plotH+16);
      lbl.setAttribute("text-anchor","middle"); lbl.setAttribute("font-size","10");
      lbl.setAttribute("fill","var(--ink-500)");
      lbl.textContent = d.label;
      g.appendChild(lbl);

      const val = document.createElementNS(svgNS,"text");
      val.setAttribute("x", x+bw/2); val.setAttribute("y", top-6);
      val.setAttribute("text-anchor","middle"); val.setAttribute("font-size","10");
      val.setAttribute("font-weight","600");
      val.setAttribute("fill", d.emph ? "var(--ink-900)" : "var(--ink-500)");
      val.textContent = opts.fmt(d.value);
      g.appendChild(val);

      rect.addEventListener("mouseenter", (e)=>showTip(el, e, `${d.label}: ${opts.fmt(d.value)}`));
      rect.addEventListener("mousemove", (e)=>moveTip(el, e));
      rect.addEventListener("mouseleave", ()=>hideTip(el));
    });

    el.innerHTML = "";
    el.appendChild(svg);
    ensureTip(el);
  }

  function lineChart(containerId, data, opts){
    const el = document.getElementById(containerId);
    if(!el) return;
    const W = 380, H = 190, padL = 8, padR = 8, padT = 20, padB = 26;
    const plotW = W - padL - padR, plotH = H - padT - padB;
    const n = data.length;
    const max = Math.max(...data.map(d=>d.value)) * 1.12;
    const min = Math.min(...data.map(d=>d.value)) * 0.9;
    const scaleX = i => (i/(n-1)) * plotW;
    const scaleY = v => plotH - ((v-min)/(max-min)) * plotH;

    const svgNS = "http://www.w3.org/2000/svg";
    const svg = document.createElementNS(svgNS,"svg");
    svg.setAttribute("viewBox", `0 0 ${W} ${H}`);
    svg.setAttribute("style","max-width:100%;height:auto;font-family:'IBM Plex Mono',monospace;");
    svg.setAttribute("role","img");
    svg.setAttribute("aria-label", opts.aria || "");

    const g = document.createElementNS(svgNS,"g");
    g.setAttribute("transform", `translate(${padL},${padT})`);
    svg.appendChild(g);

    // gridline (zero-ish baseline at min)
    [0,0.5,1].forEach(f=>{
      const y = plotH*f;
      const gl = document.createElementNS(svgNS,"line");
      gl.setAttribute("x1",0); gl.setAttribute("x2",plotW);
      gl.setAttribute("y1",y); gl.setAttribute("y2",y);
      gl.setAttribute("stroke","var(--chart-grid)"); gl.setAttribute("stroke-width","1");
      g.appendChild(gl);
    });

    const pts = data.map((d,i)=>[scaleX(i), scaleY(d.value)]);
    const path = document.createElementNS(svgNS,"path");
    const dstr = pts.map((p,i)=> (i===0?"M":"L")+p[0].toFixed(1)+","+p[1].toFixed(1)).join(" ");
    path.setAttribute("d", dstr);
    path.setAttribute("fill","none");
    path.setAttribute("stroke", opts.color);
    path.setAttribute("stroke-width","2.2");
    path.setAttribute("stroke-linecap","round");
    path.setAttribute("stroke-linejoin","round");
    g.appendChild(path);

    // area fill
    const areaD = dstr + ` L${pts[pts.length-1][0].toFixed(1)},${plotH} L0,${plotH} Z`;
    const area = document.createElementNS(svgNS,"path");
    area.setAttribute("d", areaD);
    area.setAttribute("fill", opts.color);
    area.setAttribute("opacity","0.08");
    area.setAttribute("stroke","none");
    g.insertBefore(area, path);

    data.forEach((d,i)=>{
      const [x,y] = pts[i];
      const c = document.createElementNS(svgNS,"circle");
      c.setAttribute("cx",x); c.setAttribute("cy",y); c.setAttribute("r", (i===0||i===n-1)?4:3);
      c.setAttribute("fill", opts.color);
      c.setAttribute("stroke","var(--chart-surface)"); c.setAttribute("stroke-width","1.5");
      c.style.cursor="pointer";
      g.appendChild(c);

      if(i===0||i===n-1||d.emph){
        const val = document.createElementNS(svgNS,"text");
        val.setAttribute("x",x); val.setAttribute("y", y-10);
        val.setAttribute("text-anchor", i===0?"start":(i===n-1?"end":"middle"));
        val.setAttribute("font-size","10.5"); val.setAttribute("font-weight","600");
        val.setAttribute("fill","var(--ink-900)");
        val.textContent = opts.fmt(d.value);
        g.appendChild(val);
      }

      const lbl = document.createElementNS(svgNS,"text");
      lbl.setAttribute("x",x); lbl.setAttribute("y",plotH+16);
      lbl.setAttribute("text-anchor", i===0?"start":(i===n-1?"end":"middle"));
      lbl.setAttribute("font-size","10"); lbl.setAttribute("fill","var(--ink-500)");
      lbl.textContent = d.label;
      g.appendChild(lbl);

      c.addEventListener("mouseenter",(e)=>showTip(el,e,`${d.label}: ${opts.fmt(d.value)}`));
      c.addEventListener("mousemove",(e)=>moveTip(el,e));
      c.addEventListener("mouseleave",()=>hideTip(el));
    });

    el.innerHTML = "";
    el.appendChild(svg);
    ensureTip(el);
  }

  function ensureTip(container){
    container.style.position = "relative";
    if(container.querySelector(".chart-tooltip")) return;
    const tip = document.createElement("div");
    tip.className = "chart-tooltip";
    container.appendChild(tip);
  }
  function showTip(container, evt, text){
    const tip = container.querySelector(".chart-tooltip");
    tip.textContent = text;
    tip.style.opacity = "1";
    moveTip(container, evt);
  }
  function moveTip(container, evt){
    const tip = container.querySelector(".chart-tooltip");
    const rect = container.getBoundingClientRect();
    tip.style.left = (evt.clientX - rect.left) + "px";
    tip.style.top = (evt.clientY - rect.top) + "px";
  }
  function hideTip(container){
    const tip = container.querySelector(".chart-tooltip");
    if(tip) tip.style.opacity = "0";
  }

  function render(){
    const accent = css('--accent'), accent2 = css('--accent-2'), muted = css('--ink-300');

    lineChart('chart-production', [
      {label:'2021', value:1183},
      {label:'2022', value:1159},
      {label:'2023', value:1223},
      {label:'2024', value:1327},
      {label:'2025', value:1434, emph:true},
    ], { color:accent, fmt:v=>v.toLocaleString(), aria:"총생산량 5개년 추이, 2021년 1183에서 2025년 1434 Mboe/d로 증가" });

    lineChart('chart-oilprice', [
      {label:'2021', value:66.14},
      {label:'2022', value:94.36},
      {label:'2023', value:76.85},
      {label:'2024', value:75.05},
      {label:'2025', value:64.60, emph:true},
    ], { color:accent2, fmt:v=>'$'+v.toFixed(2), aria:"평균 원유 실현가격 5개년 추이, 2022년 94.36달러에서 2025년 64.60달러로 하락" });

    barChart('chart-revenue', [
      {label:'21', value:25956},
      {label:'22', value:36634},
      {label:'23', value:28257},
      {label:'24', value:26725},
      {label:'25*', value:21593, emph:true},
    ], { color:accent, colorMuted:'color-mix(in srgb, '+accent+' 45%, transparent)', fmt:v=>'$'+(v/1000).toFixed(1)+'B', aria:"매출 5개년, 2022년 366억에서 2025년 216억 달러로 감소(2025년은 화학부문 제외 기준)" });

    barChart('chart-pretax', [
      {label:'21', value:2952},
      {label:'22', value:13007},
      {label:'23', value:5895},
      {label:'24', value:3208},
      {label:'25*', value:3052, emph:true},
    ], { color:accent2, colorMuted:'color-mix(in srgb, '+accent2+' 45%, transparent)', fmt:v=>'$'+(v/1000).toFixed(1)+'B', aria:"세전이익 5개년, 2022년 130억으로 정점 후 2025년 31억 달러" });

    barChart('chart-fcf', [
      {label:'21', value:7564},
      {label:'22', value:12313},
      {label:'23', value:6038},
      {label:'24', value:4421},
      {label:'25', value:4105, emph:true},
    ], { color:accent, colorMuted:'color-mix(in srgb, '+accent+' 45%, transparent)', fmt:v=>'$'+(v/1000).toFixed(1)+'B', aria:"잉여현금흐름 5개년, 2022년 123억에서 2025년 41억 달러로 지속 감소" });

    barChart('chart-debt', [
      {label:'21', value:29617},
      {label:'22', value:19835},
      {label:'23', value:19738},
      {label:'24', value:26117},
      {label:'25', value:22396, emph:true},
    ], { color:accent2, colorMuted:'color-mix(in srgb, '+accent2+' 45%, transparent)', fmt:v=>'$'+(v/1000).toFixed(1)+'B', aria:"총부채 5개년, 2024년 CrownRock 인수로 261억 달러까지 재상승 후 2025년 224억 달러" });
  }

  render();
  window.matchMedia('(prefers-color-scheme: dark)').addEventListener('change', render);
})();
